import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import '../models/app_enums.dart';
import '../models/user_model.dart';
class AuthRepository { AuthRepository(this._auth,this._db); final FirebaseAuth _auth; final FirebaseFirestore _db; Stream<User?> get authChanges=>_auth.authStateChanges(); Future<UserModel?> currentProfile() async { final user=_auth.currentUser; if(user==null)return null; final doc=await _db.collection('users').doc(user.uid).get(); return doc.exists?UserModel.fromFirestore(doc):null; } Future<void> signIn(String email,String password)=>_auth.signInWithEmailAndPassword(email:email,password:password); Future<void> resetPassword(String email)=>_auth.sendPasswordResetEmail(email:email); Future<void> signOut()=>_auth.signOut(); Future<void> register({required String name,required String email,required String password,required UserRole role}) async { final credential=await _auth.createUserWithEmailAndPassword(email:email,password:password); final user=UserModel(id:credential.user!.uid,name:name,email:email,role:role,status:role==UserRole.advisor?AccountStatus.pending:AccountStatus.active,createdAt:DateTime.now()); final batch=_db.batch(); batch.set(_db.collection('users').doc(user.id),user.toFirestore()); if(role==UserRole.student) batch.set(_db.collection('students').doc(user.id),{'createdAt':FieldValue.serverTimestamp()}); if(role==UserRole.advisor) batch.set(_db.collection('advisors').doc(user.id),{'status':'pending','createdAt':FieldValue.serverTimestamp()}); await batch.commit(); } }
